head.b:skin:
:root{
  --navy:#0B2D5C;
  --navy-light:#123a73;
  --navy-dark:#081f42;
  --orange:#E8751A;
  --orange-dark:#c9620f;
  --white:#FFFFFF;
  --bg-soft:#F4F6F9;
  --text:#1B222C;
  --text-muted:#5A6472;
  --border:#E4E8EF;
  --radius:10px;
  --shadow:0 4px 18px rgba(11,45,92,0.10);
  --maxw:1180px;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html{scroll-behavior:smooth}
body{font-family:'Inter',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;color:var(--text);background:var(--white);line-height:1.55;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block;height:auto}
a{color:inherit;text-decoration:none}
ul{list-style:none}
.wrap{max-width:var(--maxw);margin:0 auto;padding:0 20px}
h1,h2,h3,h4{line-height:1.2;font-weight:800;color:var(--navy)}
h2{font-size:clamp(1.5rem,4vw,2.1rem);margin-bottom:10px}
h3{font-size:1.15rem;margin-bottom:8px}
.section{padding:56px 0}
.section-soft{background:var(--bg-soft)}
.section-navy{background:var(--navy);color:var(--white)}
.section-navy h2,.section-navy h3{color:var(--white)}
.eyebrow{display:inline-block;color:var(--orange);font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:.78rem;margin-bottom:8px}
.lede{color:var(--text-muted);max-width:640px;margin-bottom:28px}
.section-navy .lede{color:#c9d6ea}

/* Buttons */
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 26px;border-radius:8px;font-weight:700;font-size:.98rem;border:2px solid transparent;transition:transform .15s ease,box-shadow .15s ease;cursor:pointer;min-height:48px}
.btn-cta{background:var(--orange);color:var(--white)}
.btn-cta:hover{background:var(--orange-dark);transform:translateY(-1px)}
.btn-outline{background:transparent;border-color:var(--white);color:var(--white)}
.btn-outline:hover{background:rgba(255,255,255,.12)}
.btn-outline-navy{background:transparent;border-color:var(--navy);color:var(--navy)}
.btn-outline-navy:hover{background:var(--navy);color:var(--white)}
.btn-block{width:100%;justify-content:center}
.btn-sm{padding:10px 18px;font-size:.88rem;min-height:auto}

/* Header */
#header-wrap{background:var(--navy);position:sticky;top:0;z-index:60;box-shadow:0 2px 10px rgba(0,0,0,.12)}
.topbar{background:var(--navy-dark);color:#cfe0f7;font-size:.82rem}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;padding:6px 20px;flex-wrap:wrap;gap:6px}
.topbar a{color:#cfe0f7}
.topbar a:hover{color:var(--orange)}
.navrow{display:flex;align-items:center;justify-content:space-between;padding:14px 20px}
.brand{display:flex;align-items:center;gap:10px;color:var(--white);font-weight:800;font-size:1.2rem}
.brand-mark{width:38px;height:38px;border-radius:8px;background:var(--orange);display:flex;align-items:center;justify-content:center;font-size:1.1rem;flex-shrink:0}
.brand-sub{display:block;font-size:.68rem;font-weight:500;color:#a9bfe0;letter-spacing:.03em}
#PageList1{margin:0}
#PageList1 .widget-content{margin:0}
.navlinks{display:flex;gap:26px;align-items:center}
.navlinks a{color:#e7edf7;font-weight:600;font-size:.95rem;padding:6px 2px;border-bottom:2px solid transparent}
.navlinks a:hover{color:var(--white);border-color:var(--orange)}
.nav-cta{margin-left:6px}
.navtoggle{display:none;flex-direction:column;gap:5px;background:none;border:none;cursor:pointer;padding:8px}
.navtoggle span{width:26px;height:2px;background:var(--white);display:block}

/* Hero */
.hero{background:linear-gradient(180deg,var(--navy) 0%,var(--navy-dark) 100%);color:var(--white);padding:64px 0 56px}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:40px;align-items:center}
.hero h1{color:var(--white);font-size:clamp(2rem,5vw,2.8rem);margin-bottom:16px}
.hero p{color:#cfe0f7;font-size:1.08rem;max-width:520px;margin-bottom:26px}
.hero-actions{display:flex;gap:14px;flex-wrap:wrap}
.hero-photo{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.15);border-radius:var(--radius);padding:18px;text-align:center;color:#a9bfe0;font-size:.85rem}
.hero-photo img{border-radius:6px;margin-bottom:10px}

/* Trust bar */
.trustbar{background:var(--white);border-bottom:1px solid var(--border)}
.trust-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:0}
.trust-item{display:flex;align-items:center;gap:10px;padding:18px 16px;border-right:1px solid var(--border);font-weight:700;font-size:.92rem;color:var(--navy)}
.trust-item:last-child{border-right:none}
.trust-ico{color:var(--orange);font-size:1.2rem;flex-shrink:0}

/* Services grid (icon grid) */
.svc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.svc-tile{background:var(--white);border:1px solid var(--border);border-radius:var(--radius);padding:20px 16px;text-align:center;transition:box-shadow .15s ease,transform .15s ease}
.svc-tile:hover{box-shadow:var(--shadow);transform:translateY(-2px);border-color:var(--orange)}
.svc-ico{width:46px;height:46px;border-radius:50%;background:var(--bg-soft);color:var(--orange);display:flex;align-items:center;justify-content:center;margin:0 auto 12px;font-size:1.35rem}
.svc-tile span{display:block;font-weight:700;font-size:.9rem;color:var(--navy)}

/* Cards / brands strip */
.brand-strip{display:flex;flex-wrap:wrap;gap:12px}
.brand-chip{background:var(--white);border:1px solid var(--border);border-radius:30px;padding:10px 20px;font-weight:700;color:var(--navy);font-size:.92rem}

/* Gallery */
.gal-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.gal-item{border-radius:var(--radius);overflow:hidden;background:var(--bg-soft);border:1px solid var(--border);aspect-ratio:4/3;display:flex;align-items:center;justify-content:center;color:var(--text-muted);font-size:.82rem;text-align:center;padding:10px;position:relative}
.gal-item img{width:100%;height:100%;object-fit:cover;position:absolute;inset:0}
.gal-cap{position:relative;z-index:1;background:rgba(11,45,92,.82);color:#fff;padding:5px 10px;border-radius:4px;font-weight:600}

/* About snippet / two-col */
.two-col{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center}

/* Footer */
#footer-wrap{background:var(--navy-dark);color:#c9d6ea}
.footer-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr 1fr;gap:32px;padding:48px 0 24px}
.footer-grid h4{color:var(--white);font-size:1rem;margin-bottom:14px}
.footer-grid p,.footer-grid li,.footer-grid a{color:#aebedb;font-size:.9rem;margin-bottom:8px;display:block}
.footer-grid a:hover{color:var(--orange)}
.footer-bottom{border-top:1px solid rgba(255,255,255,.1);padding:16px 20px;text-align:center;font-size:.82rem;color:#8ea1c6}
.footer-map{border-radius:8px;overflow:hidden;border:1px solid rgba(255,255,255,.15);margin-top:10px}
.footer-map iframe{width:100%;height:160px;border:0;display:block}

/* Sticky mobile CTA bar */
.sticky-cta{display:none;position:fixed;left:0;right:0;bottom:0;z-index:70;background:var(--white);box-shadow:0 -4px 16px rgba(0,0,0,.15);padding:10px 12px;gap:10px}
.sticky-cta a{flex:1;justify-content:center}

/* Generic page content (used by Pages: Services, About, etc.) */
.page-content{padding:44px 0 60px}
.page-content h1{font-size:clamp(1.7rem,4vw,2.3rem);margin-bottom:14px}
.page-content h2{margin-top:34px;padding-top:8px;border-top:1px solid var(--border)}
.page-content h2:first-of-type{border-top:none;margin-top:6px}
.page-content h3{margin-top:22px;color:var(--navy)}
.page-content p{color:var(--text-muted);margin-bottom:14px;max-width:760px}
.page-content .btn-cta{margin:6px 0 22px}
.page-hero{background:var(--navy);color:#fff;padding:40px 0}
.page-hero h1{color:#fff;margin-bottom:8px}
.page-hero p{color:#cfe0f7;max-width:640px}

/* Blog list */
.blog-list article{border-bottom:1px solid var(--border);padding:22px 0}
.blog-list h3 a:hover{color:var(--orange)}
.blog-list .post-meta{color:var(--text-muted);font-size:.82rem;margin-bottom:6px}
.blog-list .post-snippet{color:var(--text-muted)}

/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .hero-photo{order:-1}
  .trust-grid{grid-template-columns:repeat(2,1fr)}
  .trust-item{border-right:none;border-bottom:1px solid var(--border)}
  .svc-grid{grid-template-columns:repeat(2,1fr)}
  .gal-grid{grid-template-columns:repeat(2,1fr)}
  .two-col{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr 1fr;padding:36px 0 20px}
}
@media (max-width:720px){
  .navlinks{position:fixed;top:0;right:0;bottom:0;width:78%;max-width:300px;background:var(--navy);flex-direction:column;align-items:flex-start;padding:80px 24px 24px;transform:translateX(100%);transition:transform .25s ease;z-index:65}
  .navlinks.open{transform:translateX(0)}
  .navlinks a{width:100%;padding:12px 0;border-bottom:1px solid rgba(255,255,255,.1)}
  .navtoggle{display:flex}
  .nav-cta{margin-left:0;margin-top:10px;width:100%}
  .sticky-cta{display:flex}
  .page-content{padding-bottom:90px}
  body{padding-bottom:0}
}
@media (max-width:520px){
  .trust-grid{grid-template-columns:1fr 1fr}
  .svc-grid{grid-template-columns:1fr 1fr}
  .gal-grid{grid-template-columns:1fr 1fr}
  .footer-grid{grid-template-columns:1fr}
  .topbar .wrap{justify-content:center;text-align:center}
}

body.script:
//<![CDATA[
(function(){
  var t = document.getElementById('navToggle');
  var n = document.getElementById('navLinks');
  if(t && n){
    t.addEventListener('click', function(){ n.classList.toggle('open'); });
  }
})();
//]]>
